{
  "slides": [
    {
      "title": "榕溪路改道提案與商圈影響評估",
      "points": [
        {
          "turn": 0,
          "text": "將二百六十格停車格改為有隔離的自行車道，施工分三個階段進行。",
          "context": []
        },
        {
          "turn": 1,
          "text": "預估營業額會掉百分之十二，這是店家自己填的問卷結果。",
          "context": []
        }
      ]
    },
    {
      "title": "問卷樣本與民意調查數據爭議",
      "points": [
        {
          "turn": 3,
          "text": "兩百一十份問卷在店門口發放，不能拿來當政策依據。",
          "context": []
        },
        {
          "turn": 4,
          "text": "市府委託的一千兩百人抽樣中，七成贊成改自行車道。",
          "context": []
        }
      ]
    },
    {
      "title": "試辦成效與單車使用率數據",
      "points": [
        {
          "turn": 8,
          "text": "試辦半年事故下降百分之三十八，單車流量成長三點一倍。",
          "context": []
        },
        {
          "turn": 9,
          "text": "榕溪路平日單車使用率只有百分之四，拿掉車位客人會走。",
          "context": []
        }
      ]
    },
    {
      "title": "工程成本與店家補償機制討論",
      "points": [
        {
          "turn": 19,
          "text": "一公里工程費要二千六百萬，施工八個月店家房租誰付。",
          "context": []
        },
        {
          "turn": 20,
          "text": "用標線加膠分隔墩，一公里只要三百八十萬，可出示報價單。",
          "context": []
        }
      ]
    },
    {
      "title": "特殊族群需求與替代停車方案",
      "points": [
        {
          "turn": 38,
          "text": "七十歲以上住戶買菜看醫需停車，走到哪裡都是坡。",
          "context": []
        },
        {
          "turn": 41,
          "text": "十二格身障車位會增加到二十格，違規直接拖吊。",
          "context": []
        }
      ]
    }
  ]
}
